dict(id="S121", page="@sunyoon", speaker="SUN", format="F26", pillar="P18", hook_id="H361", hcat="IDN", title="Sun reads your knee questions", secs=48,
 prop="printed comment cards", obj="three", grammar=["DEMO"], demo=False,
 beats=[
  ("0-3","SUN","Three knee questions from you. Three blunt answers from me.","3 KNEE QUESTIONS",f"{LJ} | Sun fans out three printed comment cards (handles blurred), glasses on | CU"),
  ("3-12","SUN","One: 'I'm 82. Too late?' No. Ten nursing-home residents around 90 did eight weeks of leg training. Strength up 174 percent.","Age ~90 · 8 weeks · 10 people","same | study card inset (Fiatarone, JAMA 1990) | medium"),
  ("12-20","SUN","Small study. Ten people. But muscle still listens at ninety. Start with a chair.","Small study · muscle still listens","same | over-the-glasses look | CU"),
  ("20-30","SUN","Two: 'Is some pain okay?' Up to 3 out of 10, gone by the next morning, is usually okay. Sharper, or worse tomorrow? Back off. Ask.","≤3/10, gone by morning","same | card 2 | CU"),
  ("30-38","SUN","Three: 'New knee, can I do Chang's videos?' Your surgeon and PT first. Then Frank's version.","New knee? Surgeon + PT first.","same | card 3; Frank waves through the window | two-plane"),
  ("38-42","SUN","Hot, swollen knee? No exercise. Doctor.","Hot, swollen knee? Doctor.","same | CU | CU"),
  ("42-48","SUN","The team reads me your comments. Keep them coming. Comment KNEES for the Step Builder.","Comment KNEES","same | stacks cards | medium"),
 ],
 move=False, tags=["q_and_a"], safety="General answers only (F09/F26 rules); pain rule; red flag; comments anonymized/permissioned; AI wink.",
 regression="", cta="KNEES",
 skip="Hot, swollen knee? No exercise. Doctor.",
 caption="Comment KNEES for the Step Builder.\n1) Too late at 82? In a small JAMA 1990 study, 10 frail nursing-home residents around 90 did 8 weeks of leg training and gained 174% strength. 2) Pain: up to 3/10 that settles by the next morning is usually acceptable; sharper or worse, back off and ask. 3) New knee: surgeon and PT first.\nHot, swollen knee: see your doctor. (Comments shown with permission; handles hidden.)",
 ig=["#kneestrength","#womenover60","#askSun","#sunyoon"], tt=["#sunreadscomments","#kneestrength","#koreangrandma","#over60"],
 yt="Sun Answers Your Knee Questions (82 and Starting? Pain? New Knee?)", ev=["E03","E41"],
 note="Fiatarone 1990 (B small) stated with size; E41. Comments permissioned/anonymized (T-02).", bit="The team reads me your comments (wink)", wink=True, thumb="3 KNEE QUESTIONS", music="warm acoustic"),

